class Solution {
    fun topStudents(positiveFeedback:Array<String>,negativeFeedback:Array<String>,report:Array<String>,studentId:IntArray,k:Int):List<Int>{
        val positive=positiveFeedback.toHashSet();
        val negative=negativeFeedback.toHashSet();
        val students=report.indices.map{
            i->var score=0;
            for(word in report[i].split(" ")){
                if(word in positive)score+=3;
                if(word in negative)score--
            };
            intArrayOf(score,studentId[i])
        }.sortedWith(compareByDescending<IntArray>{
            it[0]
        }.thenBy{
            it[1]
        });
        return students.take(k).map{
            it[1]
        }
    }
}

